import orders from './orders.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'order_status',
      description: 'Get the current status of an order, optionally including its history.',
      inputSchema: {
        type: 'object',
        properties: {
          order_id: { type: 'string', description: 'The order identifier' },
          include_history: { type: 'boolean', description: 'Whether to include chronological history', default: false }
        },
        required: ['order_id'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'order_status') {
    const err = new Error(`Unknown tool: ${name}`);
    throw err;
  }

  // Validate args
  const { order_id, include_history = false } = args;
  // check extra fields
  const keys = Object.keys(args);
  for (const k of keys) {
    if (k !== 'order_id' && k !== 'include_history') {
      throw new Error(`Unexpected field: ${k}`);
    }
  }
  if (typeof order_id !== 'string') {
    throw new Error('order_id must be a string');
  }
  if ('include_history' in args && typeof include_history !== 'boolean') {
    throw new Error('include_history must be a boolean');
  }

  const order = orders[order_id];
  if (!order) {
    throw new Error(`Order not found: ${order_id}`);
  }

  let text = `status: ${order.status}`;
  if (include_history) {
    text += `\nhistory: ${order.history.join(', ')}`;
  }

  return { content: [{ type: 'text', text }] };
}
