import orders from './orders.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'order_status',
      description: 'Get the current status of an order. Optionally include the chronological history of status changes.',
      inputSchema: {
        type: 'object',
        properties: {
          order_id: { type: 'string', description: 'The order identifier.' },
          include_history: { type: 'boolean', description: 'When true, include chronological history. Defaults to false.' }
        },
        required: ['order_id'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'order_status') {
    throw new Error('Unknown tool: ' + name);
  }

  const allowed = ['order_id', 'include_history'];
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      throw new Error('Unknown argument: ' + key);
    }
  }

  const { order_id, include_history = false } = args;

  if (typeof order_id !== 'string') {
    throw new Error('order_id is required and must be a string');
  }
  if (typeof include_history !== 'boolean') {
    throw new Error('include_history must be a boolean');
  }

  if (!(order_id in orders)) {
    throw new Error('Order not found: ' + order_id);
  }

  const order = orders[order_id];
  let text = 'status: ' + order.status;
  if (include_history) {
    text += '\nhistory: ' + order.history.join(', ');
  }

  return {
    content: [{ type: 'text', text }]
  };
}

